package dev.zalard.nat;

/**
 * Entry points into the native logic (zalard_gui.dll). All of Zalard's modules, settings, configs,
 * friends, keybinds, rotations, ESP and HUD run in C++; Java only forwards Minecraft's hooks here.
 * Load the DLL first (ZalardNative.load()).
 */
public final class Z {
    private Z() {}

    // Per-release token (regenerated by tools/gen_guard.py). It is also baked into the DLL; boot()
    // refuses to start the logic unless they match, so a DLL and a jar from different builds — or a
    // swapped/patched DLL — won't run together.
    static final long TOKEN_HI = 0x1987F23B3CD92861L;
    static final long TOKEN_LO = 0x85FC36D09FE6AF31L;

    /** Once, after the DLL is loaded: checks the token, registers modules, loads the config. */
    public static native void boot(long nowMs, long nanoTime, long tokenHi, long tokenLo);

    public static void boot(long nowMs, long nanoTime) { boot(nowMs, nanoTime, TOKEN_HI, TOKEN_LO); }
    /** Start of every client tick (keybinds, modules, rotations). */
    public static native void tick(long nowMs, long nanoTime);
    /** Right before vanilla reads key presses each tick. */
    public static native void preInput(long nowMs, long nanoTime);
    /** Every rendered frame (camera aim smoothing, cursor sim). */
    public static native void frame(long nowMs, long nanoTime);
    /** World pass: ESP. */
    public static native void renderWorld(long nowMs, long nanoTime);
    /** HUD pass: ArrayList, Target HUD, watermark... */
    public static native void renderHud(long nowMs, long nanoTime);
    /** Game closing / GUI closed: write the config. */
    public static native void save();

    // ---- events from mixins
    public static native void onAttack(int entityId, boolean player, boolean living, boolean sprinting);
    public static native void onKnockback(double x, double y, double z, long nowMs);
    public static native void onExplosion(long nowMs);
    /** Velocity: filtered knockback {x, y, z}, or null to leave it alone. */
    public static native double[] filterKnockback(double x, double y, double z, boolean explosion, long nowMs);
    /** Ping Spoof: ms to hold the next keep-alive (0 = answer now). */
    public static native long pingDelay(int shownPing);

    // ---- queries from mixins
    public static final int Q_HOLDS_SPRINT = 1, Q_NO_SLOW = 2, Q_SUPPRESS_FWD = 3, Q_FORCE_BACK = 4,
                            Q_SHOW_HEAD = 5, Q_PING_SPOOF = 6,
                            Q_XRAY = 7,          // bool
                            Q_NO_OVERLAY = 8,    // bitmask: 1 fire 2 water 4 pumpkin 8 portal 16 powder 32 hurt 64 blind
                            Q_SKY_COLOR = 9,     // ARGB sky color, or 0 = leave vanilla
                            Q_VISUAL_FLAGS = 10, // bitmask: 1 fullbright 2 no-fog
                            Q_CAM_NOCLIP = 11,   // bool, third-person camera passes through blocks
                            Q_HITBOX = 12,       // 0 = off, else 1 + expand*1000 (force hitbox render + inflate)
                            Q_THRU_WALLS = 13;   // bool, combat target selection ignores blocks
    // No Overlay bits (keep in sync with native nooverlay::B_*)
    public static final int NO_FIRE = 1, NO_WATER = 2, NO_PUMPKIN = 4, NO_PORTAL = 8, NO_POWDER = 16,
                            NO_HURT = 32, NO_BLIND = 64;
    // Visual flag bits (keep in sync with native visuals::F_*)
    public static final int VF_FULLBRIGHT = 1, VF_NOFOG = 2;
    public static native int q(int what);

    /** Lag module state for the Java packet-hold handler, packed: bit0 on, bit1 mode
     *  (0 backtrack / 1 blink), bit2 release-on-hit, bits16.. hold window in ms. 0 = off. */
    public static native long lagConfig();
    /** true while Charge Stack is holding your explosion-knockback packets; false = release the queue. */
    public static native boolean chargeHold();

    /** Calls an entry with the current clocks; never lets a native problem break the game. */
    public static void run(int which) {
        long ms = System.currentTimeMillis(), ns = System.nanoTime();
        try {
            switch (which) {
                case 0 -> tick(ms, ns);
                case 1 -> preInput(ms, ns);
                case 2 -> frame(ms, ns);
                case 3 -> renderWorld(ms, ns);
                case 4 -> renderHud(ms, ns);
                default -> {}
            }
        } catch (Throwable t) { report(t); }
    }
    public static final int TICK = 0, PRE_INPUT = 1, FRAME = 2, RENDER_WORLD = 3, RENDER_HUD = 4;
    private static boolean reported;
    private static void report(Throwable t) {
        if (reported) return;
        reported = true;
        System.err.println("[Zalard] native logic call failed: " + t);
        t.printStackTrace();
    }

    // safe wrappers: a missing DLL (non-Windows) must never break the game
    public static boolean is(int what) { try { return q(what) != 0; } catch (Throwable t) { return false; } }
    /** Safe int query (for bitmasks / packed values like Q_NO_OVERLAY, Q_SKY_COLOR). 0 if the DLL isn't up. */
    public static int qi(int what) { try { return q(what); } catch (Throwable t) { return 0; } }
}
